args.ReplacementContent:
"        function resetWorkflowProgress() {
            if (confirm("Вы уверены, что хотите сбросить прогресс по этому активу?")) {
                const asset = activeAsset;
                saveWorkflowProgress(asset, quickStartMode, 0);

                // Clear any stored parameters for this asset
                localStorage.removeItem('rivenquant_config_ingest_' + asset);
                localStorage.removeItem('rivenquant_config_features_' + asset);
                localStorage.removeItem('rivenquant_config_targets_' + asset);
                localStorage.removeItem('rivenquant_config_train_table_' + asset);
                localStorage.removeItem('rivenquant_config_train_' + asset);
                localStorage.removeItem('rivenquant_config_code_' + asset);
                localStorage.removeItem('rivenquant_config_optimize_' + asset);

                renderWorkflowTimeline(asset);
                showActionToast("Прогресс сброшен.");
            }
        }"

